students = ["Ali", "Sara", "Hina"]   # Student(x) in sab ke liye sach hai
person = "Ali"                        # kis ke baare mein nateeja nikalna hai

# Rule: for all x, Student(x) -> HasLibraryCard(x)
def has_library_card(x):
    return x in students

if person in students:
    print(person, "is a student.")
    print("Conclusion:", person, "has a library card:", has_library_card(person))
else:
    print(person, "is not in the student list, so the rule gives no conclusion.")
